            add("VIX_Rising_VVIX_Falling_Long_Base", "np.where((df['VIX_Z20'] > 0) & (df['VVIX_Z20'] < 0), 1, 0)")
            add("VIX_Rising_VVIX_Falling_Short_Base", "np.where((df['VIX_Z20'] > 0) & (df['VVIX_Z20'] < 0), -1, 0)")

            add("Ratio_Mom_Long", "np.where(df['VIX_VVIX_Ratio_Z20'] > 1.0, 1, 0)")
            add("Ratio_Mom_Short", "np.where(df['VIX_VVIX_Ratio_Z20'] > 1.0, -1, 0)")
            add("Ratio_Mom_Low_Long", "np.where(df['VIX_VVIX_Ratio_Z20'] < -1.0, 1, 0)")
            add("Ratio_Mom_Low_Short", "np.where(df['VIX_VVIX_Ratio_Z20'] < -1.0, -1, 0)")
            add("Div_BothHigh20", "np.where((df['GLD'] == df['GLD'].rolling(20).max()) & (df['VIX'] == df['VIX'].rolling(20).max()), -1, 0)")
            add("Div_BothLow20", "np.where((df['GLD'] == df['GLD'].rolling(20).min()) & (df['VIX'] == df['VIX'].rolling(20).min()), 1, 0)")
